CREATE VIEW "v_wellbore_mud" AS SELECT "wellbore_mud_id", "wlbNpdidWellbore", "wlbMD", "wlbMudWeightAtMD", "wlbMudViscosityAtMD", "wlbYieldPointAtMD", "wlbMudType" FROM "reporting"."wellbore_mud";

CREATE VIEW "v_field_investment" AS SELECT "prfNpdidInformationCarrier" AS "fieldId", "prfYear" AS "investmentYear", "prfInvestmentsMillNOK" AS "investmentMillNOK" FROM "registry"."field_investment_yearly";

CREATE VIEW "v_wellbore_core_ft" AS SELECT "wellbore_core_id", "wlbNpdidWellbore", "wlbCoreNumber", "wlbCoreIntervalBottom" * 0.3048 AS "wlbCoreIntervalBottomFT" FROM "reporting"."wellbore_core" WHERE "wlbCoreIntervalUom" = '[ft  ]';
